const DIFFICULTY_NOTES: Record<string, string[]> = {
  focus: ['Needed several reminders to return to the task.', 'Distracted during the explanation; settled after a check-in.', 'Off task for much of independent work.'],
  homework: ['Homework not handed in; said they forgot.', 'No exercise book or calculator.', 'Missing homework for the second week in a row.'],
  coping: ['Found the extension task overwhelming.', 'Fell behind during the practical write-up.'],
  behaviour: ['Calling out during instructions.', 'Unsettled after lunch; moved seats.', 'Disrupting the group work.'],
  organisation: ['No exercise book today.', 'Forgot calculator.']
};

export async function loadDemoData(): Promise<void> {
  const rand = rng(20261015);
  const today = todayISO();
  const settings = await getSettings();
  const categories: Category[] = await db.categories.toArray();
  const orgCat: Category = { id: newId(), name: 'Organisation', phrase: 'being organised and prepared', builtIn: false };
  categories.push(orgCat);

  const classes: SchoolClass[] = [];
  const students: Student[] = [];
  const timetable: TimetableEntry[] = [];
  const profiles = new Map<string, Profile>();

  for (const c of CLASSES) {
    const cls: SchoolClass = { id: newId(), name: c.name, subject: c.subject, yearLevel: c.yearLevel, archived: false, createdAt: Date.now() };
    classes.push(cls);
    for (const d of c.days) timetable.push({ id: newId(), classId: cls.id, day: d, start: c.start, end: c.end, room: c.room });
    for (const [first, last, pref, profile] of c.students) {
      const s: Student = { id: newId(), classId: cls.id, firstName: first, lastName: last, preferredName: pref, archived: false, priorityAdjust: 0, createdAt: Date.now() };
      students.push(s);
      profiles.set(s.id, profile ?? {});
    }
  }
  // Ensure demo timetable has lessons near "now" on weekends too, so the in-lesson banner can be tried any day.
  for (const d of [6, 7]) timetable.push({ id: newId(), classId: classes[1].id, day: d, start: '10:00', end: '11:00', room: 'Lab 2', notes: 'Demo-only weekend lesson' });

  const byName = (f: string, l: string) => students.find((s) => s.firstName === f && s.lastName === l)!;
  const bill = byName('William', 'Harris');
  const ethan = byName('Ethan', 'Taylor');
  const jack = byName('Jack', "O'Connor");
  jack.flag = { reason: 'Monitor behaviour after the seating change', since: addDays(today, -10) };

  const coreQuestions: Question[] = await db.questions.toArray();
  const customQ: Question = {
    id: newId(), text: 'Did {name} bring the required equipment?', categoryId: orgCat.id,
    options: [{ label: 'Yes', level: 0 }, { label: 'Partly', level: 1 }, { label: 'No', level: 2 }, { label: 'Unsure', level: null }],
    allowDetail: true, classIds: [classes[0].id], studentIds: [], frequencyDays: 7, enabled: true, builtIn: false, order: 10
  };
  const questions = [...coreQuestions.map((q) => (q.builtIn ? { ...q, enabled: true } : q)), customQ];

  const adjustments: IcpAdjustment[] = [
    { id: newId(), studentId: bill.id, title: 'Preferential seating near the teacher', details: 'Front row, away from the door.', frequency: 'lesson', startDate: addDays(today, -15), active: true, createdAt: Date.now() },
    { id: newId(), studentId: bill.id, title: 'Individual teacher time', details: '2–3 minute check-in at the start of independent work.', frequency: 'daily', startDate: addDays(today, -15), active: true, createdAt: Date.now() },
    { id: newId(), studentId: bill.id, title: 'Additional time for written tasks', frequency: 'weekly', startDate: addDays(today, -15), active: true, createdAt: Date.now() },
    { id: newId(), studentId: ethan.id, title: 'Chunked task with checklist', details: 'Independent work broken into three steps on a printed checklist.', frequency: 'lesson', startDate: addDays(today, -14), active: true, createdAt: Date.now(),
      evidence: { prompt: 'Photo of a completed checklist (the work, not the student)' } }
  ];

  const checkins: Checkin[] = [];
  const observations: Observation[] = [];
  const icpChecks: IcpCheck[] = [];
  const notes: StudentNote[] = [];

  const tags: IssueTag[] = [];
  const homework: HomeworkCheck[] = [];
  const lessons: Lesson[] = [];
  const coldCalls: ColdCall[] = [];
  const swipeRand = rng(99);
  for (let back = 27; back >= 1; back--) {
    const date = addDays(today, -back);
    const wd = weekday(date);
    if (wd > 5) continue;
    for (const [ci, c] of CLASSES.entries()) {
      if (!c.days.includes(wd)) continue;
      const cls = classes[ci];
      const classStudents = students.filter((s) => s.classId === cls.id);
      const ids = new Set(classStudents.map((s) => s.id));
      if (back <= SWIPE_FROM) {
        swipeLesson(cls.id, classStudents, date, ci, c.start);
        icpForLesson(cls.id, date, wd);
        continue;
      }
      const ranked = rankStudents({
        students: classStudents, observations: observations.filter((o) => ids.has(o.studentId)),
        checkins: checkins.filter((k) => ids.has(k.studentId)), questions, categories, today: date,
        maxGapDays: settings.maxGapDays
      }).slice(0, 5);

      for (const cand of ranked) {
        const s = classStudents.find((x) => x.id === cand.studentId)!;
        const chk: Checkin = { id: checkinIdFor(date, cls.id, s.id), studentId: s.id, classId: cls.id, date, createdAt: Date.now(), status: 'complete', source: 'daily', weight: cand.weight };
        checkins.push(chk);
        if (rand() < 0.05) { chk.status = 'absent'; continue; }
        const sObs = observations.filter((o) => o.studentId === s.id);
        const profile = profiles.get(s.id)!;
        // Adjustments that have started reduce difficulty for the demo storyline.
        const helped = adjustments.some((a) => a.studentId === s.id && date >= a.startDate);
        for (const q of dueQuestions(questions, s, cls.id, sObs, date)) {
          let p = profile[q.categoryId] ?? (q.categoryId === orgCat.id ? 0.15 : 0.08);
          if (helped && (q.categoryId === 'focus' || q.categoryId === 'homework')) p *= 0.35;
          const fu = openFollowUp(sObs, q.id);
          let level: Level;
          let response: string;
          let followUp: Observation['followUp'];
          if (fu) {
            const r = rand();
            const outcome = r < p * 1.4 ? 'same' : 'improved';
            level = followUpLevel(fu.level, outcome);
            response = FOLLOW_UP_OPTIONS.find((f) => f.outcome === outcome)!.label;
            followUp = { previousId: fu.previous.id, outcome };
          } else {
            const r = rand();
            if (r >= 0.97) continue; // "Didn't see": nothing recorded
            const opt = q.options.find((x) => x.level === (r < p ? 1 : 0)) ?? q.options.find((x) => x.level !== null)!;
            level = opt.level;
            response = opt.label;
          }
          const o: Observation = {
            id: `${chk.id}|${q.id}`, checkinId: chk.id, studentId: s.id, classId: cls.id, date, createdAt: Date.now() + observations.length,
            questionId: q.id, categoryId: q.categoryId, response, level, followUp
          };
          if (level && level >= 1) {
            const pool = DIFFICULTY_NOTES[q.categoryId === orgCat.id ? 'organisation' : q.categoryId] ?? [];
            if (rand() < 0.6 && pool.length) o.note = pool[Math.floor(rand() * pool.length)];
            if (q.categoryId === 'focus') o.context = s.id === ethan.id || rand() < 0.5 ? 'Independent work' : 'Whole class';
          }
          observations.push(o);
          sObs.push(o);
        }
      }
      icpForLesson(cls.id, date, wd);
    }
  }

  for (const c of checkins) {
    const id = c.lessonId ?? `${c.date}|${c.classId}`;
    if (!lessons.some((l) => l.id === id)) {
      const t = new Date(`${c.date}T09:00:00`).getTime();
      lessons.push({ id, classId: c.classId, date: c.date, openedAt: t, closedAt: t + 3_600_000, status: 'closed', historical: true, createdAt: t });
    }
  }

  // Older format: Effort difficulties get a "low effort" detail, as the v7 upgrade does.
  for (const o of observations) {
    if (!o.source && o.questionId === 'q-focus' && (o.level ?? 0) >= 1) tags.push({ id: `${o.checkinId}|focus|low_effort`, checkinId: o.checkinId, studentId: o.studentId, classId: o.classId, date: o.date, areaId: 'focus', tagId: 'low_effort', source: 'migrated', createdAt: o.createdAt });
  }

  function icpForLesson(classId: string, date: string, wd: number) {
      for (const a of adjustments) {
        const s = students.find((x) => x.id === a.studentId)!;
        if (s.classId !== classId || date < a.startDate) continue;
        if (a.frequency === 'weekly' && wd !== 3) continue;
        const r = rand();
        icpChecks.push({
          id: `${a.id}|${date}`, adjustmentId: a.id, studentId: s.id, date, createdAt: Date.now(),
          outcome: r < 0.75 ? 'implemented' : r < 0.88 ? 'partial' : r < 0.95 ? 'not' : 'na',
          note: r >= 0.88 && r < 0.95 ? 'Relief teacher; adjustment not passed on.' : undefined
        });
      }
  }

  /**
   * One recent lesson: opened with a learning intention, homework from last lesson checked, about
   * 8 swipe check-ins (most need first), a few cold calls, then closed with the teacher's answers.
   */
  function swipeLesson(classId: string, classStudents: Student[], date: string, ci: number, start: string) {
    const subject = CLASSES[ci].subject;
    const openedAt = new Date(`${date}T${start}:00`).getTime();
    const n = lessons.filter((l) => l.classId === classId && !l.historical).length;
    const lesson: Lesson = { id: newId(), classId, date, openedAt, closedAt: openedAt + 3_540_000, status: 'closed', createdAt: openedAt,
      intention: swipeRand() < 0.85 ? INTENTIONS[subject][n % INTENTIONS[subject].length] : undefined };
    const lessonId = lesson.id;
    const inClass = <T extends { classId: string }>(xs: T[]) => xs.filter((x) => x.classId === classId);
    const prev = lessons.filter((l) => l.classId === classId).pop();
    lessons.push(lesson);
    if (prev?.homeworkSet) {
      for (const s of classStudents) {
        const p = (profiles.get(s.id)!.homework ?? 0.08) * (prev.homeworkText ? 1.4 : 2.4);
        const r = swipeRand();
        homework.push({ id: `${lessonId}|${s.id}`, lessonId, forLessonId: prev.id, classId, studentId: s.id, date, done: r >= p, ...(r < p && swipeRand() < 0.7 ? { reason: HOMEWORK_REASONS[Math.floor(swipeRand() * 3)].id } : {}), createdAt: openedAt + 60_000 });
      }
    }
    const logged = new Set<string>();
    let issues = 0;
    for (let k = 0; k < 8; k++) {
      const next = rankByNeed({ students: classStudents, checkins: inClass(checkins), observations: inClass(observations), tags: inClass(tags), homework: inClass(homework), lessons: inClass(lessons), lessonId, today: date, excludeIds: logged })[0];
      if (!next) break;
      logged.add(next.studentId);
      const t = { studentId: next.studentId, classId, date, lessonId, now: openedAt + 120_000 + k * 60_000 };
      if (swipeRand() < 0.05) {
        checkins.push({ id: `${lessonId}|${next.studentId}`, studentId: next.studentId, classId, date, lessonId, createdAt: t.now, status: 'absent', source: 'daily' });
        continue;
      }
      const profile = profiles.get(next.studentId)!;
      const helped = adjustments.some((a) => a.studentId === next.studentId && date >= a.startDate);
      const areas: Record<string, string[]> = {};
      for (const a of CHECKIN_AREAS) {
        const p = (profile[a.id] ?? 0.08) * (helped && a.id === 'focus' ? 0.35 : 1);
        if (swipeRand() < p) areas[a.id] = a.subs.filter(() => swipeRand() < 0.3).map((x) => x.id).slice(0, 2);
      }
      // Now and then a Wellbeing flag, and a minor item (gum, uniform) that isn't an issue.
      if (swipeRand() < 0.04) areas[WELLBEING.id] = [WELLBEING.subs[Math.floor(swipeRand() * WELLBEING.subs.length)].id];
      const minorOpts = CHECKIN_AREAS.find((a) => a.id === 'behaviour')!.minor ?? [];
      const minor = swipeRand() < 0.06 ? { behaviour: [minorOpts[Math.floor(swipeRand() * minorOpts.length)].id] } : undefined;
      if (Object.keys(areas).length) issues++;
      const note = areas[WELLBEING.id] ? 'Quiet and withdrawn during group work.' : areas.coping ? 'Finding the pace hard today.' : swipeRand() < 0.4 ? 'Needed several reminders.' : undefined;
      const r = Object.keys(areas).length || minor
        ? buildIssue(t, { areas, minor, note })
        : buildAllGood(t);
      checkins.push(r.checkin);
      observations.push(...r.observations);
      tags.push(...r.tags);
    }
    // A few cold calls (fair pick; "Not here" left out).
    const absent = new Set(checkins.filter((c) => c.lessonId === lessonId && c.status === 'absent').map((c) => c.studentId));
    for (let k = 0; k < 3 + Math.floor(swipeRand() * 3); k++) {
      const st = pickColdCall(classStudents, inClass(coldCalls), absent, swipeRand);
      if (!st) break;
      const good = swipeRand() < 0.7 - (profiles.get(st.id)!.focus ?? 0.08);
      const ccTags = good ? [] : STRUGGLE_TAGS.filter(() => swipeRand() < 0.35).map((x) => x.id).slice(0, 2);
      const c: ColdCall = { id: newId(), lessonId, classId, studentId: st.id, date, result: good ? 'good' : 'struggled', ...(ccTags.length ? { tags: ccTags } : {}), createdAt: openedAt + 1_200_000 + k * 120_000 };
      coldCalls.push(c);
      if (ccTags.includes('not_listening')) observations.push({ id: `cold|${c.id}`, checkinId: `cold|${lessonId}`, studentId: st.id, classId, date, createdAt: c.createdAt, questionId: 'cold-call', categoryId: 'focus', response: "Wasn't listening (cold call)", level: 1, source: 'observed', lessonId, coldCallId: c.id });
    }
    // Close: attention, homework set, and the teacher's own check. 10A's lessons feel harder to the
    // teacher even though students are mostly fine, so "My teaching" has a pattern to show.
    const tough = CLASSES[ci].name.startsWith('10A');
    lesson.attentionPct = Math.round(Math.min(95, Math.max(35, 82 - issues * 6 + (swipeRand() - 0.5) * 20)));
    lesson.homeworkSet = swipeRand() < 0.5;
    if (lesson.homeworkSet && swipeRand() < 0.7) lesson.homeworkText = HOMEWORK[subject][Math.floor(swipeRand() * 2)];
    const hr = swipeRand();
    lesson.happy = tough ? (hr < 0.65 ? 'no' : 'mostly') : hr < 0.55 ? 'yes' : hr < 0.9 ? 'mostly' : 'no';
    lesson.planDone = lesson.attentionPct > 70 ? (swipeRand() < 0.8 ? 'yes' : 'partly') : swipeRand() < 0.35 ? 'yes' : 'partly';
    if (tough && lesson.happy === 'no' && swipeRand() < 0.5) lesson.note = 'Ran out of time for the practice questions.';
  }

  // Class focus check-outs for most past lessons (own random stream, so the check-in history is unchanged).
  const rc = rng(7);
  const checkouts: Checkout[] = [];
  for (let back = 27; back >= 1; back--) {
    const date = addDays(today, -back);
    if (back <= SWIPE_FROM) continue; // later lessons record attention when they're closed
    for (const t of timetable.filter((x) => x.day === weekday(date) && !x.notes)) {
      if (rc() < 0.25) continue;
      const pct = Math.round(45 + rc() * 50);
      checkouts.push({ id: checkoutId(date, t.classId, t.id), classId: t.classId, date, timetableId: t.id, start: t.start, lessonMin: lessonLength(t), pctWorking: pct, note: pct < 55 && rc() < 0.5 ? 'Relief lesson the period before; unsettled start.' : undefined, createdAt: Date.now() });
    }
  }

  notes.push(
    { id: newId(), studentId: bill.id, date: addDays(today, -16), text: 'Parent meeting: agreed to trial front seating and short check-ins (see ICP).', createdAt: Date.now() },
    { id: newId(), studentId: ethan.id, date: addDays(today, -14), text: 'Responds well to a printed checklist during practical write-ups.', createdAt: Date.now() },
    { id: newId(), studentId: jack.id, date: addDays(today, -10), text: 'Moved to the front table this week.', createdAt: Date.now() }
  );

  // Round 6: yesterday a fictional relief teacher took the first class; their check-ins wait for review.
  const reliefDay = addDays(today, -1);
  const reliefPass: ReliefPass = { id: newId(), classId: classes[0].id, from: reliefDay, to: reliefDay, reliefName: 'Sam Relief', shareIcp: false, plan: 'Read chapter 4 and answer the questions.', createdAt: Date.now() - 2 * 86_400_000 };
  checkins.filter((c) => c.classId === classes[0].id && c.date === reliefDay && c.status === 'complete').slice(0, 3)
    .forEach((c) => { c.relief = { passId: reliefPass.id, name: 'Sam Relief' }; c.createdAt = Date.now() - 86_400_000; });

  await db.transaction('rw', [db.classes, db.students, db.timetable, db.categories, db.questions, db.checkins, db.observations, db.icpAdjustments, db.icpChecks, db.notes, db.plans, db.checkouts, db.issueTags, db.homework, db.lessons, db.coldCalls], async () => {
    await db.lessons.bulkAdd(lessons);
    await db.coldCalls.bulkAdd(coldCalls);
    await db.issueTags.bulkAdd(tags);
    await db.homework.bulkAdd(homework);
    await db.checkouts.bulkAdd(checkouts);
    await db.classes.bulkAdd(classes);
    await db.students.bulkAdd(students);
    await db.timetable.bulkAdd(timetable);
    await db.categories.add(orgCat);
    await db.questions.add(customQ);
    await db.checkins.bulkAdd(checkins);
    await db.observations.bulkAdd(observations);
    await db.icpAdjustments.bulkAdd(adjustments);
    await db.icpChecks.bulkAdd(icpChecks);
    await db.notes.bulkAdd(notes);
    await db.plans.where('id').startsWith(planId(today, '')).delete();
  });
  // Round 4: an active assessment with a couple of checks in the first class, and journal entries.
  const c0 = classes[0];
  const c0Lessons = lessons.filter((l) => l.classId === c0.id && !l.historical).sort((a, b) => b.openedAt - a.openedAt);
  const task: Assessment = { id: newId(), classId: c0.id, name: 'Persuasive essay', dueDate: addDays(today, 9), checkpoints: ['Plan', 'Draft', 'Final'], createdAt: Date.now() };
  const assessmentChecks: AssessmentCheck[] = c0Lessons[0] ? students.filter((s) => s.classId === c0.id).slice(0, 10).map((s, i) => ({
    id: `${task.id}|${c0Lessons[0].id}|${s.id}`, assessmentId: task.id, classId: c0.id, studentId: s.id, lessonId: c0Lessons[0].id, date: c0Lessons[0].date,
    result: i % 4 === 1 ? 'behind' : 'on_track', ...(i % 4 === 1 ? { reasons: ['missing_research'] } : {}), checkpoint: 'Plan', createdAt: c0Lessons[0].openedAt + 600_000 + i
  })) : [];
  const journal: JournalEntry[] = [
    { id: newId(), classId: c0.id, date: addDays(today, -6), lessonId: c0Lessons[2]?.id, text: 'Tried a silent start with the do-now on the board. Much calmer first ten minutes.', tags: ['Behaviour management', 'Lesson design'], aitsl: 4, createdAt: Date.now() },
    { id: newId(), classId: c0.id, date: addDays(today, -2), lessonId: c0Lessons[0]?.id, text: 'Mentor observed. Feedback: more wait time after questions; cold call worked well.', tags: ['Mentor feedback', 'Engagement'], aitsl: 3, createdAt: Date.now() }
  ];
  await db.transaction('rw', [db.assessments, db.assessmentChecks, db.journal, db.reliefPasses], async () => {
    await db.assessments.add(task);
    await db.assessmentChecks.bulkAdd(assessmentChecks);
    await db.journal.bulkAdd(journal);
    await db.reliefPasses.add(reliefPass);
  });
  await demoSeating(classes[3], students, { checkins, observations, tags, homework, lessons }, today);
  await saveSettings({ currentClassId: classes[0].id });
}

/** Round 7: relationships, seating needs, support levels, a balance tag, a room and an active plan for 8B. */
async function demoSeating(cls: SchoolClass, all: Student[], hist: { checkins: Checkin[]; observations: Observation[]; tags: IssueTag[]; homework: HomeworkCheck[]; lessons: Lesson[] }, today: string) {
  const students = all.filter((s) => s.classId === cls.id);
  const by = (f: string) => students.find((s) => s.firstName === f)!;
  const now = Date.now();
  const rel = (a: string, b: string, type: Relationship['type'], extra: Partial<Relationship> = {}): Relationship => ({
    id: newId(), classId: cls.id, studentA: by(a).id, studentB: by(b).id, type, strength: 1, source: 'manual', confirmed: true, date: addDays(today, -20), createdAt: now, updatedAt: now, ...extra
  });
  const relationships: Relationship[] = [
    rel('Ali', 'Sam', 'keepApart', { strength: 2, note: 'Ongoing conflict since Term 2.' }),
    rel('Jayden', 'Dylan', 'keepApart'),
    rel('Mia', 'Hannah', 'worksWell'), rel('Priya', 'Chloe', 'worksWell'), rel('Ravi', 'Ben', 'worksWell'), rel('Marco', 'Sofia', 'worksWell'),
    // Two peer-conflict signals from check-ins: shows as a suggestion. One works-well signal: listed under "From check-ins".
    rel('Tom', 'Nate', 'keepApart', { source: 'checkin', confirmed: false, date: addDays(today, -5) }),
    rel('Nate', 'Tom', 'keepApart', { source: 'checkin', confirmed: false, date: addDays(today, -12) }),
    rel('Lena', 'Freya', 'worksWell', { source: 'checkin', confirmed: false, date: addDays(today, -4) })
  ];
  const tagEal = { id: newId(), name: 'EAL', noAlone: true };
  cls.balanceTags = [tagEal, { id: newId(), name: 'New this term', noAlone: false }];
  by('Priya').seatingNeeds = ['front', 'near_board'];
  by('Ravi').seatingNeeds = ['near_door'];
  by('Hannah').seatingNeeds = ['left_handed'];
  by('Jayden').seatingNeeds = ['near_teacher'];
  for (const f of ['Marco', 'Sofia', 'Rosa']) by(f).balanceTags = [tagEal.id];
  by('Callum').balanceTags = [cls.balanceTags[1].id];
  // Support levels are only used once "Use support levels" is switched on in Settings → Seating.
  by('Arjun').support = newSupport('more', addDays(today, -14));
  by('Jade').support = newSupport('extension', addDays(today, -14));
  by('Chloe').support = newSupport('on_track', addDays(today, -14));
  by('Felix').support = { level: 'on_track', setAt: addDays(today, -80), reviewBy: addDays(today, -10) };
  const adjustments: IcpAdjustment[] = [
    { id: newId(), studentId: by('Priya').id, title: 'Seated near the front', details: 'Vision: needs to see the board clearly.', frequency: 'lesson', startDate: addDays(today, -20), active: true, createdAt: now },
    { id: newId(), studentId: by('Ravi').id, title: 'Movement breaks', details: 'Short break outside the room when needed.', frequency: 'lesson', startDate: addDays(today, -20), active: true, createdAt: now },
    { id: newId(), studentId: by('Aisha').id, title: 'Reduced distractions', frequency: 'lesson', startDate: addDays(today, -20), active: true, createdAt: now }
  ];
  // Evie: Wellbeing → friendship issues three days ago (being left out never separates students).
  const lesson = hist.lessons.filter((l) => l.classId === cls.id && !l.historical && l.date <= addDays(today, -2)).sort((a, b) => b.openedAt - a.openedAt)[0];
  const extra = lesson ? buildIssue({ studentId: by('Evie').id, classId: cls.id, date: lesson.date, lessonId: lesson.id }, { areas: { wellbeing: ['friendship'] }, note: 'Sat alone at lunch; quiet in group work.', followUp: true }) : null;

  const room: Room = { id: newId(), name: 'H3', createdAt: now, ...roomTemplate('fours', 24) };
  const tagsAll = [...hist.tags, ...(extra?.tags ?? [])];
  const need = needByStudent(students, hist.checkins, hist.observations, tagsAll, hist.homework, today, hist.lessons);
  const report = makePlan({
    room, students: plannerStudents({ students, tags: tagsAll, adjustments, concern: new Map([...need].map(([id, r]) => [id, r.concern])), useSupport: false, today }),
    relationships: plannerRelationships(relationships), noAloneTags: [{ id: tagEal.id, name: 'EAL' }], options: { useSupport: false, supportTable: false, minimiseChanges: false }, seed: 7
  });
  const plan: SeatingPlan = {
    id: newId(), classId: cls.id, roomId: room.id, name: 'Term 4 plan', room: { rows: room.rows, cols: room.cols, cells: room.cells },
    seats: Object.fromEntries(Object.entries(report.seats).map(([seat, id]) => [seat, { studentId: id }])), active: true, activeFrom: addDays(today, -13), createdAt: now
  };
  const evie = by('Evie');
  evie.seatWatch = newWatch(plan.id, seatLabel(plan, evie.id) ?? 'Table 1', 'left_out', addDays(today, -1));
  await db.transaction('rw', [db.classes, db.students, db.relationships, db.rooms, db.seatingPlans, db.icpAdjustments, db.checkins, db.observations, db.issueTags], async () => {
    await db.classes.put(cls);
    await db.students.bulkPut(students);
    await db.relationships.bulkAdd(relationships);
    await db.rooms.add(room);
    await db.seatingPlans.add(plan);
    await db.icpAdjustments.bulkAdd(adjustments);
    if (extra) {
      await db.observations.where('checkinId').equals(extra.checkin.id).delete();
      await db.issueTags.where('checkinId').equals(extra.checkin.id).delete();
      await db.checkins.put(extra.checkin);
      await db.observations.bulkPut(extra.observations);
      await db.issueTags.bulkPut(extra.tags);
    }
  });
}
